def add_demo_deliverables(apps, schema_editor):
    Deliverable = apps.get_model("projects", "Deliverable")
    Project = apps.get_model("projects", "Project")
    if Deliverable.objects.exists():
        return
    projects = {p.name: p for p in Project.objects.filter(name__in={d[0] for d in DELIVERABLES})}
    if len(projects) < 6:
        return
    for name, title, due, delivered in DELIVERABLES:
        day = date(2026, int(due[:2]), int(due[3:]))
        Deliverable.objects.create(project=projects[name], name=title, due_date=day, delivered_on=day if delivered else None)


